fn add_list(arr1: &Vec<i32>, arr2: &Vec<i32>) -> Vec<i32> {
    // Since we assume `arr1` and `arr2` have the same length
    // and that each pairwise sum fits in an i32, we can safely zip
    // their iterators, sum element‐wise, and collect into a new Vec.
    arr1
        .iter()
        .zip(arr2.iter())
        .map(|(&x, &y)| x + y)
        .collect()
}

